class Solution {
public:
    int largestSubmatrix(vector<vector<int>>& matrix) {
        int m = matrix.size();
        int n = matrix[0].size();
        vector<int> heights(n, 0);
        vector<int> order(n);
        vector<int> next(n);
        iota(order.begin(), order.end(), 0);
        int ans = 0;
        for (int r = 0; r < m; r++) {
            for (int i = 0; i < n; i++) {
                int c = order[i];
                if (matrix[r][c] == 1) heights[c]++;
                else heights[c] = 0;
            }
            int idx = 0;
            for (int i = 0; i < n; i++) {
                if (heights[order[i]] == 0) next[idx++] = order[i];
            }
            for (int i = 0; i < n; i++) {
                if (heights[order[i]] > 0) next[idx++] = order[i];
            }
            swap(order, next);
            for (int i = 0; i < n; i++) {
                int c = order[i];
                if (heights[c] == 0) continue;
                int area = heights[c] * (n - i);
                if (area > ans) ans = area;
            }
        }
        return ans;
    }
};
